import {GameStore} from './store.js';
import {derivedCharacter,mod,signed,rollDice,shuffle,randomId,XP_THRESHOLDS,cardinal,clamp} from './rules.js';
import {ApiClient} from './api.js';
import {CardLibrary} from './cards.js';
import {SharedMap} from './map.js';
import {CombatEngine} from './combat.js';
import {InputController} from './input.js';
import {ImmersiveDiceRoller} from './dice-roller.js';
import {MultiplayerController} from './multiplayer.js';
import {BackendHub} from './backend-hub.js';
import {$,$$,escapeHtml,toast,feedHtml,setPage,showResult,formatTime} from './ui.js';

const JSON_FILES=['config','campaign','characters','decks','maps','controls','runtime'];
let resources,store,api,cards,map,combat,input,dice3d,multiplayer,backendHub,botTimer,pollTimer,deferredInstallPrompt=null;
const boot=(message,progress)=>{$('#bootMessage').textContent=message;$('#bootProgress').style.width=`${progress}%`};

main().catch(error=>{console.error(error);boot(`Could not open the game: ${error.message}`,100);$('#bootProgress').style.background='#ef5d67'});

async function main(){
  boot('Reading game rules and original card library…',18);
  const loaded=await Promise.all(JSON_FILES.map(async name=>{const r=await fetch(`assets/json/${name}.json`,{cache:'no-store'});if(!r.ok)throw new Error(`Missing ${name}.json`);return [name,await r.json()]}));
  resources=Object.fromEntries(loaded);resources.characters=resources.characters.characters;resources.decks=resources.decks.decks;resources.maps=resources.maps.maps;
  store=new GameStore(resources);store.state.backendUrl=resources.config.backendUrl;store.state.online=store.state.online||{lobby:null,matchId:'',match:null,chat:[],clientSequence:0,lastSyncAt:''};store.state.online.chat=store.state.online.chat||[];store.save();api=new ApiClient(resources.config.backendUrl);
  boot('Preparing character sheets and 5-foot maps…',48);
  cards=new CardLibrary(resources.decks,archiveCard);
  map=new SharedMap({canvas:$('#mapCanvas'),viewport:$('#mapViewport'),maps:resources.maps,characters:resources.characters,onMove:commitMove,onInteract:interact});
  combat=new CombatEngine(store,resources,text=>addFeed(text));
  dice3d=new ImmersiveDiceRoller({stage:$('#diceStage'),result:$('#characterDiceResult'),onResult:r=>{addFeed(`${currentCharacter().name} rolled ${r.expression}: ${r.total}.`);$('#lastRoll').innerHTML=`<strong>${r.total}</strong> · ${escapeHtml(r.expression)}${r.critical?' · Critical!':''}${r.fumble?' · Natural 1':''}`}});
  const requestedPage=location.hash.slice(1);if(requestedPage&&document.getElementById(`page-${requestedPage}`))store.state.activePage=requestedPage;bindUi();multiplayer=new MultiplayerController({store,api,resources,refresh:pollOnlineState,navigate});backendHub=new BackendHub({store,api,resources,onLobby:applyOnlineLobby,navigate});cards.init();renderAll();configureInput();applySettings();setupInstall();registerServiceWorker();
  boot('The Keep is ready.',100);setTimeout(()=>{$('#bootScreen').remove();$('#app').hidden=false;map.center()},350);
  if(store.state.session.started&&store.state.session.mode==='offline')startBotMotion();
  if(api.configured&&store.state.account?.token)resumeOnline().catch(error=>{console.warn('Online resume failed',error);toast(error.message,'error')});
}

function currentCharacter(){const base=resources.characters.find(c=>c.id===store.state.selectedCharacterId)||resources.characters[0];return derivedCharacter(base,store.state.level,store.state.xp)}
function mapRecord(){return resources.maps.find(m=>m.id===store.state.session.mapId)||resources.maps[0]}
function deck(id){return resources.decks[id]||[]}
function allCards(){return Object.values(resources.decks).flat()}
function cardById(id){return allCards().find(c=>c.id===id)}

function bindUi(){
  $$('[data-page]').forEach(el=>el.addEventListener('click',()=>navigate(el.dataset.page)));
  $('#navToggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
  $('#startOfflineButton').addEventListener('click',startOffline);
  $('#openConnectButton').addEventListener('click',()=>$('#connectDialog').showModal());
  $('#dialogGoSettings').addEventListener('click',()=>setTimeout(()=>navigate('settings')));
  $('#clearFeed').addEventListener('click',()=>store.update(s=>s.session.feed=[],'feed-clear'));
  $('#partySize').addEventListener('change',e=>e.target.value=clamp(Number(e.target.value),4,8));
  $('#startingLevel').addEventListener('change',e=>{const level=clamp(Number(e.target.value),1,20);store.update(s=>{s.level=level;s.xp=XP_THRESHOLDS[level-1]},'level-set')});
  $('#reducedMotionQuick').addEventListener('change',e=>{store.update(s=>s.settings.reducedMotion=e.target.checked,'setting');applySettings()});
  $$('.sheet-tabs button').forEach(button=>button.addEventListener('click',()=>{store.update(s=>s.sheetTab=button.dataset.sheetTab,'sheet-tab');renderCharacter();if(button.dataset.sheetTab==='dice')dice3d.activate()}));
  $('#addXpButton').addEventListener('click',()=>store.update(s=>s.xp+=100,'xp'));
  $('#levelUpButton').addEventListener('click',()=>{if(store.state.level>=20)return toast('This character is already level 20.');store.update(s=>{s.level++;s.xp=Math.max(s.xp,XP_THRESHOLDS[s.level-1])},'level-up')});
  $('#characterNotes').addEventListener('input',e=>store.update(s=>s.privateNotes[s.selectedCharacterId]=e.target.value,'notes'));
  $('#homeMapSelect').addEventListener('change',e=>selectMap(e.target.value));$('#mapSelect').addEventListener('change',e=>selectMap(e.target.value));
  $('#floorSelect').addEventListener('change',e=>store.update(s=>s.session.floor=e.target.value,'floor'));
  $('#gridToggle').addEventListener('click',e=>{map.showGrid=!map.showGrid;e.currentTarget.classList.toggle('active',map.showGrid);map.draw()});
  $('#fogToggle').addEventListener('click',e=>{map.fog=!map.fog;e.currentTarget.classList.toggle('active',map.fog);map.draw()});
  $('#centerMapButton').addEventListener('click',()=>map.center());$('#zoomOutButton').addEventListener('click',()=>map.setZoom(map.zoom-.1));$('#zoomInButton').addEventListener('click',()=>map.setZoom(map.zoom+.1));
  $('#combatModeToggle').addEventListener('click',()=>toggleCombat());
  $('#perceptionButton').addEventListener('click',perceptionPulse);$('#submitAccusation').addEventListener('click',submitAccusation);
  $$('.dice-row button').forEach(b=>b.addEventListener('click',()=>{$('#diceExpression').value=`1d${b.dataset.die}`;performRoll()}));$('#rollDiceButton').addEventListener('click',performRoll);$$('[data-action="open-dice"]').forEach(b=>b.addEventListener('click',openCharacterDice));
  $('#characterDiceRoll').addEventListener('click',()=>dice3d.roll($('#characterDiceExpression').value,$('#characterDiceMode').value,`${currentCharacter().shortName||currentCharacter().name} sheet roll`).catch(()=>{}));
  $$('[data-quick-3d]').forEach(b=>b.addEventListener('click',()=>{$('#characterDiceExpression').value=b.dataset.quick3d;dice3d.roll(b.dataset.quick3d,$('#characterDiceMode').value,`${currentCharacter().shortName||currentCharacter().name} sheet roll`).catch(()=>{})}));
  $('#diceFullscreen').addEventListener('click',()=>{$('#characterDiceShell').classList.toggle('fullscreen');$('#diceFullscreen').textContent=$('#characterDiceShell').classList.contains('fullscreen')?'Exit Full Screen':'Full Screen';dice3d.activate()});
  $('#startCombatButton').addEventListener('click',toggleCombat);$('#endTurnButton').addEventListener('click',()=>{combat.next();renderCombat()});$('#addMonsterButton').addEventListener('click',addRandomMonster);$('#clearCombatLog').addEventListener('click',()=>store.update(s=>s.session.combat.log=[],'combat-log-clear'));
  $$('[data-phase]').forEach(b=>b.addEventListener('click',()=>changePhase(b.dataset.phase)));$('#revealSeedButton').addEventListener('click',revealSeed);
  $('#spawnEvidenceButton').addEventListener('click',()=>spawnEntity('evidence'));$('#spawnTrapButton').addEventListener('click',()=>spawnEntity('trap'));$('#spawnMonsterHostButton').addEventListener('click',()=>spawnEntity('monster'));$('#spawnTreasureButton').addEventListener('click',()=>spawnEntity('treasure'));
  $('#saveBackendButton').addEventListener('click',saveBackend);$('#testBackendButton').addEventListener('click',testBackend);$('#resetLocalButton').addEventListener('click',resetLocal);
  $('#showPasswordToggle').addEventListener('change',e=>$('#accountPassword').type=e.target.checked?'text':'password');
  $('#settingsInstallButton').addEventListener('click',installApp);$('#installAppButton').addEventListener('click',installApp);$('#controllerDeadzone').addEventListener('input',e=>{if(input)input.deadzone=Number(e.target.value)/100;store.update(s=>s.settings.controllerDeadzone=Number(e.target.value),'setting')});
  $('#leaveLiveMatchButton').addEventListener('click',leaveLiveMatch);
  $('#registerButton').addEventListener('click',registerOnline);$('#loginButton').addEventListener('click',loginOnline);$('#logoutButton').addEventListener('click',logoutOnline);
  $('#createLobbyButton').addEventListener('click',createOnlineLobby);$('#joinLobbyButton').addEventListener('click',joinOnlineLobby);$('#readyLobbyButton').addEventListener('click',toggleLobbyReady);$('#startLiveMatchButton').addEventListener('click',startLiveMatch);$('#leaveLobbyButton').addEventListener('click',leaveOnlineLobby);$('#saveLobbySettingsButton').addEventListener('click',saveLobbySettings);$('#onlineLobbySummary').addEventListener('click',handleLobbyMemberAction);
  for(const [id,key] of [['settingReducedMotion','reducedMotion'],['settingHighContrast','highContrast'],['settingLargeText','largeText'],['settingGridLabels','gridLabels']])$('#'+id).addEventListener('change',e=>{store.update(s=>s.settings[key]=e.target.checked,'setting');applySettings();renderMap()});
  $('#settingScale').addEventListener('input',e=>{store.update(s=>s.settings.scale=Number(e.target.value),'setting');applySettings()});
  bindTouchControls();
  store.addEventListener('change',e=>onStoreChange(e.detail.reason));
}

function configureInput(){
  input=new InputController({
    map:()=>navigate('map'),character:()=>navigate('character'),cards:()=>navigate('cards'),journal:()=>navigate('journal'),multiplayer:()=>navigate('multiplayer'),dice:()=>openCharacterDice(),
    interact:interactNearby,inspect:()=>store.state.session.mode==='online'?navigate('multiplayer'):perceptionPulse(),search:perceptionPulse,crouch:toggleCrouch,sneak:toggleSneak,jump:()=>sendControlAction('jump',()=>addFeed(`${currentCharacter().name} jumps in place.`)),escape:controllerBack,confirm:controllerConfirm,
    primary:()=>store.state.activePage==='combat'&&$('#combatActions button:not([disabled])')?.click(),secondary:toggleCrouch,
    forward:o=>map.move('forward',o),back:o=>map.move('back',o),left:o=>map.move('left',o),right:o=>map.move('right',o),turnLeft:()=>map.turn(-90),turnRight:()=>map.turn(90),focusMap:()=>{},
    isGameplayActive:()=>store.state.activePage==='map'&&store.state.session.started,
    gamepadStatus:renderGamepadStatus
  });input.deadzone=Number(store.state.settings.controllerDeadzone||36)/100;input.bind();
}
function controllerConfirm(){const el=document.activeElement;if(el&&el.matches('button,a[href]'))el.click();else if(store.state.activePage==='map')interactNearby()}
function controllerBack(){const dialog=document.querySelector('dialog[open]');if(dialog){dialog.close();return}if($('#sidebar').classList.contains('open')){$('#sidebar').classList.remove('open');return}navigate('home')}
function renderGamepadStatus(gp){const text=gp?`Controller: ${gp.id.replace(/\s*\([^)]*\)/g,'').slice(0,36)}`:'Controller: none';$('#gamepadBadge').textContent=text;$('#gamepadBadge').className=`badge ${gp?'badge-online':'badge-muted'}`;$('#controllerStatusText').textContent=gp?'Controller connected':'No controller detected';$('#controllerDetails').textContent=gp?`${gp.id} · ${gp.mapping||'generic'} mapping · keyboard and touch remain active.`:'Pair a controller by USB or Bluetooth, then press a button.'}
function bindTouchControls(){let timer=null;const stop=()=>{clearInterval(timer);timer=null};$('#touchControls').addEventListener('pointerdown',e=>{const b=e.target.closest('[data-touch]');if(!b)return;e.preventDefault();const a=b.dataset.touch,fire=()=>{if(a==='forward'||a==='back')map.move(a);else if(a==='strafe-left')map.move('left');else if(a==='strafe-right')map.move('right');else if(a==='sprint')map.move('forward',{sprint:true});else if(a==='left')map.turn(-90);else if(a==='right')map.turn(90);else if(a==='interact')interactNearby()};fire();if(['forward','back','strafe-left','strafe-right','sprint'].includes(a))timer=setInterval(fire,170)});['pointerup','pointercancel','pointerleave'].forEach(type=>$('#touchControls').addEventListener(type,stop))}


function onStoreChange(reason){
  if(['setting','notes'].includes(reason))return;
  renderAll();
}

function navigate(page){if(!document.getElementById(`page-${page}`))page='home';store.state.activePage=page;store.save();try{history.replaceState(null,'',`#${page}`)}catch{}setPage(page);$('#sidebar').classList.remove('open');if(page==='map'){requestAnimationFrame(()=>{map.draw();map.center()})}if(page==='multiplayer')multiplayer?.refreshNow();if(page==='services')backendHub?.refreshAll(false)}

function renderAll(){renderHome();renderCharacter();renderMap();renderCards();renderJournal();renderCombat();renderHost();renderSettings();renderChrome();multiplayer?.render();}

function renderChrome(){const c=currentCharacter(),s=store.state.session,connected=!!store.state.account?.token;$('#topPortrait').src=c.portrait;$('#topCharacterName').textContent=c.shortName||c.name;$('#modeLabel').textContent=s.mode==='offline'?'Offline training':'Connected multiplayer';$('#phaseBadge').textContent=title(s.phase);$('#connectionBadge').textContent=connected?(store.state.online?.matchId?'Live':'Signed in'):'Offline';$('#connectionBadge').className=`badge ${connected?'badge-online':'badge-offline'}`;setPage(store.state.activePage||'home')}

function renderHome(){
  const c=currentCharacter(),s=store.state.session;$('#premiseText').textContent=resources.campaign.premise;$('#characterCount').textContent=`${resources.characters.length} restored sheets`;
  $('#characterPicker').innerHTML=resources.characters.map(ch=>`<button class="character-choice ${ch.id===c.id?'selected':''}" data-character="${ch.id}"><img src="${escapeHtml(ch.portrait)}" alt="${escapeHtml(ch.name)}"><strong>${escapeHtml(ch.name)}</strong><small>${escapeHtml(ch.className)} · ${escapeHtml(ch.appearanceRace)}</small></button>`).join('');
  $$('#characterPicker [data-character]').forEach(b=>b.addEventListener('click',()=>store.update(st=>st.selectedCharacterId=b.dataset.character,'character-select')));
  const options=resources.maps.map(m=>`<option value="${m.id}" ${m.id===s.mapId?'selected':''}>${escapeHtml(m.name)}</option>`).join('');$('#homeMapSelect').innerHTML=options;$('#partySize').value=Math.max(4,s.party.length||8);$('#startingLevel').value=store.state.level;$('#reducedMotionQuick').checked=store.state.settings.reducedMotion;
  $('#metricPlayers').textContent=s.party.length;$('#metricEvidence').textContent=s.evidence.length;$('#metricObjectives').textContent=s.objectives.filter(o=>!o.complete).length;
  $('#partyPreview').innerHTML=partyHtml(s.party);$('#sessionFeed').innerHTML=feedHtml(s.feed);
  const role=$('#roleNotice');if(s.role){role.hidden=false;role.innerHTML=`<strong>Private role:</strong> ${escapeHtml(title(s.role))}. ${s.role==='killer'?'Complete the hidden ritual or escape with the relic without being correctly accused.':'Gather evidence and identify the killer, weapon, and room.'}`}else role.hidden=true;
}

function renderCharacter(){
  const c=currentCharacter();$('#characterPortrait').src=c.portrait;$('#characterName').textContent=c.name;$('#characterLevel').textContent=c.level;$('#characterSubtitle').textContent=`${c.appearanceRace} ${c.className} (${c.subclass}) · ${c.concept}`;
  $('#identityGrid').innerHTML=[c.pronouns,c.background,c.alignment,c.size,`${c.speed} ft speed`,`${c.ac} AC`].map(x=>`<span>${escapeHtml(x)}</span>`).join('');$('#xpText').textContent=`${c.xp.toLocaleString()} XP · next level ${c.xpNext.toLocaleString()}`;$('#xpFill').style.width=`${c.xpPercent}%`;
  $$('.sheet-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.sheetTab===store.state.sheetTab));$$('.sheet-section').forEach(s=>s.classList.toggle('active',s.id===`sheet-${store.state.sheetTab}`));
  $('#sheet-overview').innerHTML=`<div class="stat-grid">${Object.entries(c.scores).map(([a,v])=>`<div class="ability-card"><b>${escapeHtml(a)}</b><strong>${v}</strong><span>${signed(mod(v))}</span></div>`).join('')}</div><div class="sheet-grid"><section class="paper-panel" style="grid-column:span 4"><h2>Defenses</h2><table><tr><th>Armor Class</th><td>${c.ac}</td></tr><tr><th>Maximum HP</th><td>${c.hp}</td></tr><tr><th>Proficiency</th><td>${signed(c.prof)}</td></tr><tr><th>Initiative</th><td>${signed(mod(c.scores.Dexterity))}</td></tr><tr><th>Speed</th><td>${c.speed} ft</td></tr><tr><th>Hit Die</th><td>d${c.hitDie}</td></tr></table><h3>Saving Throws</h3><table>${Object.entries(c.saves).map(([k,v])=>`<tr><td>${k}</td><td>${signed(v)}</td></tr>`).join('')}</table></section><section class="paper-panel" style="grid-column:span 4"><h2>Skills</h2><table>${Object.entries(c.skills).map(([k,v])=>`<tr><td>${k}</td><td>${signed(v)}</td></tr>`).join('')}</table></section><section class="paper-panel" style="grid-column:span 4"><h2>Features</h2><div class="feature-list">${c.features.map(f=>`<div class="feature-item"><strong>${escapeHtml(f.name)}</strong><small>Level ${f.level}</small><p>${escapeHtml(f.summary)}</p>${f.resource?`<span class="resource-pill">${escapeHtml(f.resource.label)} · ${escapeHtml(f.resource.reset)} rest</span>`:''}</div>`).join('')}</div></section></div>`;
  $('#sheet-actions').innerHTML=`<div class="sheet-grid"><section class="paper-panel" style="grid-column:span 6"><h2>Attacks</h2><div class="feature-list">${(c.attacks||[]).map(a=>`<div class="feature-item"><strong>${escapeHtml(a.name)}</strong><p>${escapeHtml(a.damage)} · ${escapeHtml(a.range)}</p><small>${escapeHtml(a.notes||'')}</small><button class="small sheet-roll" data-roll="1d20+${mod(c.scores[a.ability]||10)+c.prof}">Roll attack</button></div>`).join('')}</div></section><section class="paper-panel" style="grid-column:span 6"><h2>Spells & Powers</h2><div class="spell-list">${(c.spells||[]).map(sp=>`<div class="spell-item"><strong>${escapeHtml(sp.name)}</strong><small>${sp.spellLevel===0?'Cantrip':`Level ${sp.spellLevel}`}</small><p>${escapeHtml(sp.summary)}</p></div>`).join('')||'<p>No spells on this sheet.</p>'}</div></section></div>`;
  $('#sheet-actions').querySelectorAll('.sheet-roll').forEach(b=>{b.classList.add('sheet-roll-3d');b.textContent='Roll attack in 3D';b.addEventListener('click',()=>{openCharacterDice();$('#characterDiceExpression').value=b.dataset.roll;dice3d.roll(b.dataset.roll,'normal','Attack Roll').catch(()=>{})})});
  $('#sheet-inventory').innerHTML=`<section class="paper-panel"><h2>Equipment & Digital Items</h2><div class="inventory-list">${[...(c.equipment||[]),...resources.campaign.starterLoadout.map(id=>cardById(id)?.name||id)].map(i=>`<div class="inventory-item">${escapeHtml(i)}</div>`).join('')}</div><h3>Progression note</h3><p>${escapeHtml(c.progressionNote||'')}</p></section>`;
  dice3d?.setCharacter(c);$('#diceCharacterPortrait').src=c.portrait;$('#diceCharacterName').textContent=`${c.shortName||c.name}'s Dice`;
  $('#galleryTitle').textContent=`${c.name} — Supplied Art Gallery`;$('#characterGallery').innerHTML=(c.gallery||[]).map((src,i)=>`<figure class="gallery-card"><img src="${escapeHtml(src)}" alt="${escapeHtml(c.name)} supplied artwork ${i+1}" loading="lazy"><figcaption>Supplied character artwork ${i+1}</figcaption></figure>`).join('')||'<p class="muted">The primary portrait and token are available for this character.</p>';
  const m=mapRecord(),mini=$('#miniMapMount'),session=store.state.session;mini.style.backgroundImage=`linear-gradient(#0018,#0018),url('${m.art}')`;
  mini.innerHTML=session.party.map(p=>{const pos=session.positions[p.playerId],ch=resources.characters.find(x=>x.id===p.characterId);if(!pos||pos.floor!==session.floor)return'';return `<span class="mini-token ${p.playerId===session.playerId?'local':''}" title="${escapeHtml(p.name)}" style="left:${((pos.x+.5)/(m.grid?.columns||48))*100}%;top:${((pos.y+.5)/(m.grid?.rows||32))*100}%"><img src="${escapeHtml(ch?.token||ch?.portrait||'')}" alt="${escapeHtml(p.name)}"></span>`}).join('');
  $('#characterNotes').value=store.state.privateNotes[c.id]||'';
}

function renderMap(){
  const s=store.state.session,m=mapRecord();const options=resources.maps.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${escapeHtml(x.name)}</option>`).join('');$('#mapSelect').innerHTML=options;
  $('#floorSelect').innerHTML=(m.floors||['F1']).map(f=>`<option ${f===s.floor?'selected':''}>${escapeHtml(f)}</option>`).join('');if(!(m.floors||[]).includes(s.floor))s.floor=m.floors?.[0]||'F1';
  if(map.map?.id!==m.id)map.selectMap(m.id);map.setFloor(s.floor);map.labels=store.state.settings.gridLabels;map.setState({players:s.party,positions:s.positions,entities:s.entities,localId:s.playerId,facing:s.facing});map.setZoom(s.zoom||1);
  $('#distanceReadout').textContent=`${s.movedFeet} ft`;$('#movementStatus').innerHTML=`<div class="movement-chip"><span>Mode</span><strong>${s.combat.active?'Combat turn':'Exploration'}</strong></div><div class="movement-chip"><span>Speed</span><strong>${currentCharacter().speed} ft</strong></div><div class="movement-chip"><span>Posture</span><strong>${s.crouched?'Crouched':s.sneaking?'Sneaking':'Standing'}</strong></div>`;
  $('#combatModeToggle').textContent=s.combat.active?'Leave combat movement':'Enter combat movement';
}

function renderCards(){cards.setState({hand:store.state.session.hand,archive:store.state.session.archive});cards.render()}

function renderJournal(){
  const s=store.state.session;$('#objectiveList').innerHTML=s.objectives.map(o=>`<label class="objective-item check"><input type="checkbox" data-objective="${o.id}" ${o.complete?'checked':''}><span><strong>${escapeHtml(o.title)}</strong><small>${escapeHtml(o.description||'')}</small></span></label>`).join('')||'<p class="muted">Start a match to receive objectives.</p>';
  $$('#objectiveList [data-objective]').forEach(x=>x.addEventListener('change',()=>store.update(st=>{const o=st.session.objectives.find(v=>v.id===x.dataset.objective);if(o)o.complete=x.checked},'objective')));
  $('#evidenceTimeline').innerHTML=feedHtml(s.evidence.map(e=>({time:e.time,text:e.text||cardById(e.cardId)?.name||'Evidence'})));
  fillSelect($('#accuseSuspect'),deck('suspects'));fillSelect($('#accuseWeapon'),deck('weapons'));fillSelect($('#accuseRoom'),deck('rooms'));
}

function renderCombat(){
  const c=currentCharacter(),cs=store.state.session.combat;$('#roundLabel').textContent=`Round ${cs.round}`;$('#startCombatButton').textContent=cs.active?'End Encounter':'Start Encounter';
  $('#combatTurnLabel').textContent=cs.active&&cs.initiative.length?`${cs.initiative[cs.turnIndex]?.name}'s turn`:'No active encounter';
  $('#initiativeList').innerHTML=cs.initiative.map((i,index)=>`<div class="initiative-item ${index===cs.turnIndex?'active':''}"><span><strong>${escapeHtml(i.name)}</strong><small>${escapeHtml(i.type)}</small></span><b>${i.initiative}</b></div>`).join('')||'<p class="muted">Start an encounter to roll initiative.</p>';
  $('#combatActions').innerHTML=(c.attacks||[]).map(a=>`<button class="action-card" data-attack="${escapeHtml(a.name)}"><strong>${escapeHtml(a.name)}</strong><small>${escapeHtml(a.damage)} · ${escapeHtml(a.range)}</small></button>`).join('')+`<button class="action-card" data-action-roll="perception"><strong>Search / Perception</strong><small>1d20${signed(c.skills.Perception)}</small></button>`;
  $$('#combatActions [data-attack]').forEach(b=>b.addEventListener('click',()=>attackMonster(b.dataset.attack)));$$('#combatActions [data-action-roll]').forEach(b=>b.addEventListener('click',perceptionPulse));
  $('#encounterList').innerHTML=cs.monsters.map(m=>`<div class="list-item"><strong>${escapeHtml(m.name)}</strong><small>AC ${m.ac} · ${m.hp}/${m.maxHp} HP</small><div class="hp-bar"><span style="width:${Math.max(0,m.hp/m.maxHp*100)}%"></span></div></div>`).join('')||'<p class="muted">No monsters in the encounter.</p>';$('#combatLog').innerHTML=feedHtml(cs.log);
}

function renderHost(){$('#hostPartyList').innerHTML=partyHtml(store.state.session.party);$('#hostAuthorityBadge').textContent=api.configured?'Backend URL configured':'Offline host simulation'}
function renderSettings(){const s=store.state.settings;$('#backendUrlInput').value=resources.config.backendUrl;$('#backendStatusText').textContent=api.configured?'Supplied v1 deployment configured':'Configuration error';$('#settingReducedMotion').checked=s.reducedMotion;$('#settingHighContrast').checked=s.highContrast;$('#settingLargeText').checked=s.largeText;$('#settingGridLabels').checked=s.gridLabels;$('#settingScale').value=s.scale;$('#controllerDeadzone').value=s.controllerDeadzone||36;$('#controlsTableWrap').innerHTML=controlsTable(resources.controls.actions);renderOnline()}

function startOffline(){
  const partySize=clamp(Number($('#partySize').value)||8,4,8),selected=currentCharacter(),others=shuffle(resources.characters.filter(c=>c.id!==selected.id)).slice(0,partySize-1),partyChars=[selected,...others];
  const suspect=shuffle(deck('suspects').filter(c=>partyChars.some(p=>p.id===c.id)))[0],weapon=shuffle(deck('weapons'))[0],room=shuffle(deck('rooms'))[0],killerId=suspect.id;
  const mapData=mapRecord(),spawns=mapData.spawnCells?.length?mapData.spawnCells:Array.from({length:partySize},(_,i)=>[22+i%4,14+Math.floor(i/4)]);
  const players=partyChars.map((ch,i)=>({playerId:i===0?'local-player':`bot-${i}`,characterId:ch.id,name:i===0?'You':ch.shortName||ch.name,role:ch.id===killerId?'killer':'investigator',online:true}));
  const positions=Object.fromEntries(players.map((p,i)=>{const spawn=spawns[i%spawns.length],sx=Array.isArray(spawn)?spawn[0]:spawn?.x,sy=Array.isArray(spawn)?spawn[1]:spawn?.y,sf=Array.isArray(spawn)?null:spawn?.floor;return[p.playerId,{x:Number(sx??22),y:Number(sy??15),floor:sf||mapData.floors?.[0]||'F1'}]}));
  const solutionIds=new Set([suspect.id,weapon.id,room.id]);const dealable=shuffle([...deck('suspects'),...deck('weapons'),...deck('rooms')].filter(c=>!solutionIds.has(c.id)));const hand=dealable.slice(0,Math.min(5,dealable.length)).map(c=>c.id);
  store.update(s=>{s.session.started=true;s.session.mode='offline';s.session.phase='preparation';s.session.role=selected.id===killerId?'killer':'investigator';s.session.seed={suspectId:suspect.id,weaponId:weapon.id,roomId:room.id,killerPlayerId:players.find(p=>p.characterId===killerId)?.playerId};s.session.party=players;s.session.positions=positions;s.session.floor=mapData.floors?.[0]||'F1';s.session.hand=hand;s.session.archive=[];s.session.evidence=[];s.session.entities=[];s.session.objectives=makeObjectives(s.session.role);s.session.feed=[{time:formatTime(),text:'The storm seals the Keep. Private cards and roles have been dealt.'}];s.session.movedFeet=0;s.session.combat={active:false,round:0,turnIndex:0,initiative:[],monsters:[],log:[]}},'match-start');
  startBotMotion();navigate('home');toast(`Offline match started as ${title(store.state.session.role)}.`);setTimeout(()=>changePhase('exploration'),1100);
}

function makeObjectives(role){return role==='killer'?[{id:'ritual',title:'Prepare the dark ritual',description:'Visit three marked locations without exposing your role.',complete:false},{id:'relic',title:'Secure the relic',description:'Find and carry the hidden relic.',complete:false},{id:'escape',title:'Reach the ground escape route',description:'Escape before a correct accusation.',complete:false}]:[{id:'evidence-3',title:'Archive three evidence cards',description:'Use Perception Pulse or investigate map entities.',complete:false},{id:'question',title:'Question another adventurer',description:'Use an interaction near another visible token.',complete:false},{id:'accuse',title:'Solve the three-part mystery',description:'Name the killer, weapon, and crime location.',complete:false}]}

function startBotMotion(){clearInterval(botTimer);botTimer=setInterval(()=>{const s=store.state.session;if(!s.started||s.combat.active||s.phase==='voting'||document.hidden)return;store.update(st=>{const g=mapRecord().grid||{columns:48,rows:32};for(const p of st.session.party.filter(p=>p.playerId!==st.session.playerId)){const pos=st.session.positions[p.playerId];if(!pos)continue;const [dx,dy]=shuffle([[1,0],[-1,0],[0,1],[0,-1],[0,0]])[0];pos.x=clamp(pos.x+dx,0,g.columns-1);pos.y=clamp(pos.y+dy,0,g.rows-1)}},'bot-move')},1500)}

function commitMove(move){
  const s=store.state.session;if(!s.started)return toast('Start an offline match before moving.');const speed=currentCharacter().speed;if(s.combat.active&&s.movedFeet+move.distanceFeet>speed)return toast(`Combat movement is limited to ${speed} feet this turn.`,'error');
  store.update(st=>{st.session.positions[st.session.playerId]={...(st.session.positions[st.session.playerId]||{}),x:move.x,y:move.y,floor:st.session.floor};st.session.facing=move.facing;st.session.movedFeet+=move.distanceFeet},'move');
  if(api.configured&&s.mode==='online'&&store.state.online.matchId&&store.state.account.token){const sequence=Number(store.state.online.clientSequence||0)+1;store.state.online.clientSequence=sequence;store.save();api.move(store.state.account.token,store.state.online.matchId,{...move,floor:s.floor,location:move.location||map.currentLocation()},sequence).catch(err=>{toast(err.message,'error');pollOnlineState().catch(()=>{})})}
}

function toggleCrouch(){store.update(s=>{s.session.crouched=!s.session.crouched;if(s.session.crouched)s.session.sneaking=false},'posture');toast(store.state.session.crouched?'Crouched.':'Standing.')}
function toggleSneak(){store.update(s=>{s.session.sneaking=!s.session.sneaking;if(s.session.sneaking)s.session.crouched=false},'posture');toast(store.state.session.sneaking?'Sneaking.':'No longer sneaking.')}
function interactNearby(){if(store.state.session.mode==='online'&&store.state.online?.matchId){navigate('multiplayer');const evidence=(store.state.online.match?.evidence||[]).find(e=>e.location===map.currentLocation()&&!(e.discoveredBy||[]).includes(store.state.account.player?.id));if(evidence){const {token}=store.state.account;api.discoverEvidence(token,store.state.online.matchId,evidence.id).then(()=>multiplayer.refreshNow()).catch(error=>toast(error.message,'error'))}return}const pos=store.state.session.positions[store.state.session.playerId];const nearby=store.state.session.entities.find(e=>Math.abs(e.x-pos.x)+Math.abs(e.y-pos.y)<=1);if(nearby)interact(nearby.id);else{addFeed(`${currentCharacter().name} checks the nearby corridor.`);completeObjective('question')}}
function interact(id){const e=store.state.session.entities.find(x=>x.id===id);if(!e)return;if(e.type==='evidence'){archiveRandomEvidence(e.cardId);store.update(s=>s.session.entities=s.session.entities.filter(x=>x.id!==id),'entity-remove')}else if(e.type==='trap'){const r=rollDice('1d20+2');showResult(r.total>=12?'Trap avoided':'Trap triggered',r.total>=12?`You notice ${e.name} in time.`:`${e.name} activates. Mark the effect in combat.`)}else if(e.type==='monster'){navigate('combat');if(!store.state.session.combat.monsters.length)addRandomMonster()}else if(e.type==='treasure'){showResult('Treasure found',e.name||'A locked chest waits here.')}else addFeed(`Interacted with ${e.name||e.type}.`)}

function perceptionPulse(){if(!store.state.session.started)return toast('Start a match first.');if(store.state.session.mode==='online'){const {token}=store.state.account;return api.discoverEvidence(token,store.state.online.matchId,'').then(()=>{toast('Search sent to the server.');multiplayer.refreshNow()}).catch(error=>toast(error.message,'error'))}const c=currentCharacter(),r=rollDice(`1d20+${c.skills.Perception}`);if(r.total>=12){archiveRandomEvidence();showResult('Perception success',`You rolled ${r.total} and found a usable clue.`)}else showResult('Nothing certain',`You rolled ${r.total}. The Keep gives you only shadows and half-heard footsteps.`);return r}
function archiveRandomEvidence(preferred){const s=store.state.session,seed=s.seed||{},forbidden=new Set([seed.suspectId,seed.weaponId,seed.roomId]);const possible=[...deck('suspects'),...deck('weapons'),...deck('rooms')].filter(c=>!forbidden.has(c.id)&&!s.archive.includes(c.id));const card=preferred?cardById(preferred):shuffle(possible)[0];if(!card)return toast('No new evidence cards remain.');archiveCard(card,`Evidence rules out ${card.name}.`)}
function archiveCard(card,text){if(!card)return;store.update(s=>{if(!s.session.archive.includes(card.id))s.session.archive.push(card.id);s.session.evidence.push({id:randomId('evidence'),cardId:card.id,time:formatTime(),text:text||`${card.name} was archived as evidence.`});const o=s.session.objectives.find(x=>x.id==='evidence-3');if(o&&s.session.archive.length>=3)o.complete=true},'evidence');toast(`${card.name} archived.`)}

function submitAccusation(){const s=store.state.session;if(!s.seed)return toast('No active mystery seed.');const guess={suspectId:$('#accuseSuspect').value,weaponId:$('#accuseWeapon').value,roomId:$('#accuseRoom').value};const correct=Object.keys(guess).every(k=>guess[k]===s.seed[k]);if(correct){completeObjective('accuse');changePhase('resolution');showResult('Mystery solved!',`The accusation is correct: ${cardById(guess.suspectId)?.name}, using ${cardById(guess.weaponId)?.name}, in the ${cardById(guess.roomId)?.name}.`,'success')}else{showResult('The accusation fails','At least one part is wrong. In a connected game the backend records the configured penalty without exposing the hidden seed.','error');addFeed('A formal accusation failed. The killer gains time.')}}

function performRoll(){openCharacterDice();$('#characterDiceExpression').value=$('#diceExpression').value;$('#characterDiceMode').value=$('#rollMode').value;dice3d.roll($('#diceExpression').value,$('#rollMode').value,'Combat Dice').catch(error=>toast(error.message,'error'))}
function openCharacterDice(){store.update(s=>{s.activePage='character';s.sheetTab='dice'},'sheet-tab');renderAll();setPage('character');requestAnimationFrame(()=>dice3d.activate())}
function toggleCombat(){const cs=store.state.session.combat;if(cs.active)combat.end();else combat.start(currentCharacter());renderCombat();renderMap()}
function addRandomMonster(){const monster=shuffle(deck('monsters'))[0];combat.addMonster(monster);if(store.state.session.combat.active)combat.start(currentCharacter());renderCombat()}
function attackMonster(name){const c=currentCharacter(),base=(c.attacks||[]).find(a=>a.name===name),target=store.state.session.combat.monsters.find(m=>m.hp>0);if(!target)return toast('Add a monster to the encounter first.');const bonus=mod(c.scores[base.ability]||10)+c.prof;const damage=(base.damage.match(/\d+d\d+(?:\s*[+-]\s*\d+)?/)||['1d6'])[0].replace(/\s/g,'');combat.attack(c.name,target,bonus,damage);renderCombat()}

function changePhase(phase){store.update(s=>{s.session.phase=phase;s.session.feed.push({time:formatTime(),text:`Match phase changed to ${title(phase)}.`})},'phase');toast(`${title(phase)} phase.`)}
function revealSeed(){const seed=store.state.session.seed;if(!seed)return toast('Start a match first.');$('#seedDisplay').hidden=false;$('#seedDisplay').innerHTML=`<strong>Killer:</strong> ${escapeHtml(cardById(seed.suspectId)?.name)}<br><strong>Weapon:</strong> ${escapeHtml(cardById(seed.weaponId)?.name)}<br><strong>Room:</strong> ${escapeHtml(cardById(seed.roomId)?.name)}`}
function spawnEntity(type){if(!store.state.session.started)return toast('Start a match first.');const pos=store.state.session.positions[store.state.session.playerId]||{x:24,y:16};const source=type==='evidence'?shuffle([...deck('suspects'),...deck('weapons'),...deck('rooms')])[0]:shuffle(deck(type==='monster'?'monsters':type==='trap'?'traps':'treasure'))[0];const entity={id:randomId(type),type,x:clamp(pos.x+Math.floor(Math.random()*7)-3,0,47),y:clamp(pos.y+Math.floor(Math.random()*7)-3,0,31),floor:store.state.session.floor,name:source?.name||title(type),cardId:source?.id};store.update(s=>s.session.entities.push(entity),'spawn');toast(`${entity.name} placed on the map.`)}

function selectMap(id){const m=resources.maps.find(x=>x.id===id);store.update(s=>{s.session.mapId=id;s.session.floor=m?.floors?.[0]||'F1';s.session.zoom=1},'map-select')}
function completeObjective(id){store.update(s=>{const o=s.session.objectives.find(x=>x.id===id);if(o)o.complete=true},'objective')}
function addFeed(text){store.update(s=>{s.session.feed.push({time:formatTime(),text});if(s.session.feed.length>80)s.session.feed.shift()},'feed')}


function requireOnlineReady(){if(!api.configured)throw new Error('Deploy the backend and save its /exec URL first.');if(!store.state.account?.token)throw new Error('Sign in or register first.');return store.state.account.token}
function selectedBackendClass(){return currentCharacter().backendClassId||'class_1'}
function characterForClass(classId){return resources.characters.find(c=>c.backendClassId===classId)||resources.characters[0]}
function frontendMapId(value){const needle=String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');return resources.maps.find(m=>m.id.replace(/-/g,'_')===needle||m.name.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')===needle)?.id||resources.config.defaultMapId}
function onlineValue(id){return String($(id)?.value||'').trim()}

async function registerOnline(){try{if(!api.configured)saveBackend();if(!api.configured)throw new Error('Save the deployed Apps Script /exec URL first.');const email=onlineValue('#accountEmail'),username=onlineValue('#accountUsername'),password=$('#accountPassword').value,displayName=onlineValue('#accountDisplayName')||username;const data=await api.register(email,username,password,displayName);store.update(s=>{s.account={token:data.token,player:data.player,expiresAt:data.expiresAt};s.online={lobby:null,matchId:'',match:null,chat:[],clientSequence:0,lastSyncAt:''}},'online-auth');toast(`Signed in as ${data.player.displayName}.`);startOnlinePolling();backendHub?.onAccountChanged()}catch(error){toast(error.message,'error')}}
async function loginOnline(){try{if(!api.configured)saveBackend();if(!api.configured)throw new Error('Save the deployed Apps Script /exec URL first.');const data=await api.login(onlineValue('#accountLogin')||onlineValue('#accountEmail')||onlineValue('#accountUsername'),$('#accountPassword').value);store.update(s=>{s.account={token:data.token,player:data.player,expiresAt:data.expiresAt};s.online={lobby:null,matchId:'',match:null,chat:[],clientSequence:0,lastSyncAt:''}},'online-auth');toast(`Welcome back, ${data.player.displayName}.`);startOnlinePolling();backendHub?.onAccountChanged()}catch(error){toast(error.message,'error')}}
async function logoutOnline(){const token=store.state.account?.token;try{if(token&&api.configured)await api.logout(token)}catch(error){console.warn(error)}clearInterval(pollTimer);store.update(s=>{s.account={token:'',player:null,expiresAt:''};s.online={lobby:null,matchId:'',match:null,chat:[],clientSequence:0,lastSyncAt:''};if(s.session.mode==='online')s.session={...s.session,mode:'offline',started:false,phase:'lobby',party:[],positions:{},playerId:'local-player',role:null}},'online-logout');toast('Signed out.');backendHub?.onAccountChanged()}
async function resumeOnline(){const token=requireOnlineReady();const data=await api.me(token);store.update(s=>{s.account.player=data.player||data;s.account.token=token},'online-auth');startOnlinePolling();backendHub?.onAccountChanged()}
async function createOnlineLobby(){try{const token=requireOnlineReady();const selected=mapRecord(),m=selected.onlineEnabled?selected:resources.maps.find(x=>x.onlineEnabled);if(!m)throw new Error('No backend-compatible online map is available.');const maxPlayers=clamp(Number($('#lobbyMaxPlayers').value)||8,4,8);if(![4,6,8].includes(maxPlayers))throw new Error('Online rooms support 4, 6, or 8 players.');const data=await api.createLobby(token,{name:onlineValue('#lobbyName')||'Killer In The Keep',visibility:$('#lobbyVisibility').value,maxPlayers,mapName:m.name,classId:selectedBackendClass(),requireReady:true,textChat:true,voiceChat:true,crossplay:true});applyOnlineLobby(data.lobby);toast(`Lobby ${data.lobby.roomCode} created for up to ${maxPlayers} players.`);startOnlinePolling()}catch(error){toast(error.message,'error')}}
async function joinOnlineLobby(){try{const token=requireOnlineReady(),code=onlineValue('#lobbyRoomCode').toUpperCase();if(code.length!==6)throw new Error('Enter the six-character room code.');const data=await api.joinLobby(token,code,selectedBackendClass());if(Number(data.lobby.maxPlayers)>8||Number(data.lobby.members?.length)>8){await api.leaveLobby(token,data.lobby.id).catch(()=>{});throw new Error('That room exceeds this game’s eight-character limit.')}const duplicates=(data.lobby.members||[]).filter(m=>m.classId===selectedBackendClass());if(duplicates.length>1){await api.leaveLobby(token,data.lobby.id).catch(()=>{});throw new Error('That character is already claimed. Choose one of the remaining character sheets.')}applyOnlineLobby(data.lobby);toast(`Joined ${data.lobby.name}.`);startOnlinePolling()}catch(error){toast(error.message,'error')}}
async function toggleLobbyReady(){try{const token=requireOnlineReady(),lobby=store.state.online.lobby;if(!lobby)throw new Error('Create or join a lobby first.');const me=lobby.members.find(m=>m.playerId===store.state.account.player?.id),claimed=lobby.members.find(m=>m.playerId!==me?.playerId&&m.classId===selectedBackendClass());if(claimed)throw new Error(`${characterForClass(selectedBackendClass()).name} is already claimed by another player.`);const data=await api.readyLobby(token,lobby.id,!me?.ready,selectedBackendClass());applyOnlineLobby(data.lobby);toast(!me?.ready?'Marked ready.':'Marked not ready.')}catch(error){toast(error.message,'error')}}
async function startLiveMatch(){try{const token=requireOnlineReady(),lobby=store.state.online.lobby;if(!lobby)throw new Error('Create or join a lobby first.');const members=lobby.members||[];if(members.length<4||members.length>8)throw new Error('A match requires four to eight players.');if(new Set(members.map(m=>m.classId)).size!==members.length)throw new Error('Every player must claim a different one of the eight characters.');if(members.some(m=>!m.ready&&m.playerId!==lobby.hostPlayerId))throw new Error('Every non-host player must be ready.');const data=await api.startMatch(token,lobby.id);applyOnlineMatch(data.match);toast('The live match has begun.');startOnlinePolling();navigate('multiplayer')}catch(error){toast(error.message,'error')}}
async function leaveOnlineLobby(){try{const token=requireOnlineReady(),lobby=store.state.online.lobby;if(lobby)await api.leaveLobby(token,lobby.id);store.update(s=>{s.online.lobby=null;s.online.matchId='';if(s.session.mode==='online'){s.session.started=false;s.session.mode='offline';s.session.phase='lobby';s.session.party=[];s.session.positions={};s.session.playerId='local-player'}},'online-lobby');toast('Left the live lobby.')}catch(error){toast(error.message,'error')}}
function applyOnlineLobby(lobby){if(Number(lobby?.maxPlayers||0)>8||Number(lobby?.members?.length||0)>8)throw new Error('This frontend only supports lobbies of up to eight players.');store.update(s=>{s.online.lobby=lobby;s.online.matchId=lobby.matchId||s.online.matchId||'';s.online.lastSyncAt=new Date().toISOString()},'online-lobby')}
function applyOnlineMatch(match){if(!match)return;const playerId=store.state.account.player?.id,players=Object.values(match.players||{});if(players.length>8)throw new Error('The backend returned more than the eight supported character slots.');const own=match.players?.[playerId],mapId=frontendMapId(match.mapId||match.mapName),mapData=resources.maps.find(m=>m.id===mapId)||resources.maps[0];const party=players.map(p=>{const ch=characterForClass(p.classId);return{playerId:p.playerId,characterId:ch.id,name:p.displayName||ch.shortName||ch.name,role:p.role||'',online:p.connected!==false,alive:p.alive!==false}});const positions={};for(const p of players){const raw=p.position||{},zone=mapData.zones?.find(z=>z.name===p.location),fallback=zone?.position||[0,0],hasServerPosition=Math.abs(Number(raw.x||0))+Math.abs(Number(raw.z??raw.y??0))>0;positions[p.playerId]={x:clamp(Number(hasServerPosition?raw.x:fallback[0]),0,(mapData.grid?.columns||48)-1),y:clamp(Number(hasServerPosition?(raw.z??raw.y):fallback[1]),0,(mapData.grid?.rows||32)-1),floor:zone?.floor||mapData.floors?.[0]||'F1',location:p.location||zone?.name||''}}const ownChar=characterForClass(own?.classId),ownZone=mapData.zones?.find(z=>z.name===own?.location);const roomPosition=name=>mapData.zones?.find(z=>z.name===name)?.position||[0,0];const entities=[...(match.evidence||[]).filter(e=>e.location===own?.location).map(e=>{const pos=roomPosition(e.location);return{id:e.id,type:'evidence',name:e.name||e.type||'Evidence',x:pos[0],y:pos[1],floor:mapData.zones?.find(z=>z.name===e.location)?.floor||mapData.floors?.[0]||'F1'}}),...(match.bodies||[]).filter(b=>!b.reported).map(b=>{const pos=roomPosition(b.location);return{id:b.id,type:'body',name:'Fallen adventurer',x:pos[0],y:pos[1],floor:mapData.zones?.find(z=>z.name===b.location)?.floor||mapData.floors?.[0]||'F1'}})];store.update(s=>{s.selectedCharacterId=ownChar.id;s.online.matchId=match.id;s.online.match=match;s.online.lastSyncAt=new Date().toISOString();s.session.mode='online';s.session.started=match.status==='active';s.session.playerId=playerId;s.session.matchId=match.id;s.session.phase=String(match.phase||'Exploration').toLowerCase();s.session.mapId=mapId;s.session.floor=ownZone?.floor||mapData.floors?.[0]||'F1';s.session.role=own?.role||null;s.session.party=party;s.session.positions=positions;s.session.entities=entities;s.session.facing=Number(own?.rotation||0);s.session.objectives=(own?.tasks||[]).map(t=>({id:t.id,title:t.name,description:`${t.type||'Task'} · ${t.durationSeconds||0}s`,complete:t.status==='completed'}));s.session.feed=s.session.feed||[]},'online-sync');clearInterval(botTimer);multiplayer?.render()}


async function saveLobbySettings(){try{const token=requireOnlineReady(),lobby=store.state.online.lobby;if(!lobby)throw new Error('Create or join a lobby first.');if(!lobby.isHost)throw new Error('Only the lobby host can change lobby settings.');const mapChoice=mapRecord(),onlineMap=mapChoice.onlineEnabled?mapChoice:resources.maps.find(m=>m.onlineEnabled);const data=await api.updateLobby(token,lobby.id,{name:onlineValue('#lobbyName')||lobby.name,visibility:$('#lobbyVisibility').value,mapName:onlineMap.name,voiceChat:true,textChat:true,crossplay:true,requireReady:true});applyOnlineLobby(data.lobby);toast('Lobby settings saved. The eight-player frontend limit remains enforced.')}catch(error){toast(error.message,'error')}}
async function handleLobbyMemberAction(event){const button=event.target.closest('[data-lobby-action]');if(!button)return;try{const token=requireOnlineReady(),lobby=store.state.online.lobby;if(!lobby?.isHost)throw new Error('Only the lobby host can manage members.');const action=button.dataset.lobbyAction,target=button.dataset.playerId;if(action==='kick'){const d=await api.kickLobby(token,lobby.id,target);applyOnlineLobby(d.lobby);toast('Player removed from the lobby.')}else if(action==='ban'){const d=await api.banLobby(token,lobby.id,target);applyOnlineLobby(d.lobby);toast('Player banned from this lobby.')}}catch(error){toast(error.message,'error')}}

function renderOnline(){const account=store.state.account||{},lobby=store.state.online?.lobby;$('#accountStatusText').textContent=account.player?`${account.player.displayName} signed in`:'Signed out';$('#logoutButton').disabled=!account.token;$('#createLobbyButton').disabled=!account.token;$('#joinLobbyButton').disabled=!account.token;$('#lobbyStatusText').textContent=lobby?`${lobby.name} · ${lobby.members?.length||0}/${lobby.maxPlayers}`:'No lobby';$('#lobbyRoomCode').value=lobby?.roomCode||$('#lobbyRoomCode').value;const summary=$('#onlineLobbySummary');if(!lobby){summary.innerHTML='<p class="muted">The supplied backend is configured. Sign in to create or join a four-to-eight-player lobby.</p>';$('#readyLobbyButton').disabled=true;$('#startLiveMatchButton').disabled=true;$('#leaveLobbyButton').disabled=true;return}const isHost=!!lobby.isHost,me=lobby.members?.find(m=>m.playerId===account.player?.id);$('#readyLobbyButton').disabled=false;$('#readyLobbyButton').textContent=me?.ready?'Not Ready':'Ready';$('#startLiveMatchButton').disabled=!isHost;$('#leaveLobbyButton').disabled=false;summary.innerHTML=`<div><strong>${escapeHtml(lobby.name)}</strong> · <span class="lobby-code">${escapeHtml(lobby.roomCode||'PRIVATE')}</span><p class="muted">${escapeHtml(lobby.visibility)} · ${escapeHtml(lobby.mapName||'Keep map')} · ${lobby.members.length}/${lobby.maxPlayers} players${isHost?' · You are host':''}</p></div><div class="online-member-grid">${lobby.members.map(member=>{const ch=characterForClass(member.classId);return `<div class="online-member"><img src="${escapeHtml(ch.portrait)}" alt=""><span><strong>${escapeHtml(member.displayName)}</strong><small>${escapeHtml(ch.name)} · ${member.ready?'Ready':'Not ready'}${member.playerId===lobby.hostPlayerId?' · Host':''}</small></span>${isHost&&member.playerId!==lobby.hostPlayerId?`<span class="button-row"><button data-lobby-action="kick" data-player-id="${escapeHtml(member.playerId)}">Kick</button><button class="danger ghost" data-lobby-action="ban" data-player-id="${escapeHtml(member.playerId)}">Ban</button></span>`:''}</div>`}).join('')}</div>`}
function startOnlinePolling(){clearInterval(pollTimer);if(!api.configured||!store.state.account?.token)return;pollTimer=setInterval(()=>pollOnlineState().then(()=>multiplayer?.loadChat()).catch(error=>console.warn('Online poll failed',error)),Number(resources.config.pollIntervalMs||1200));pollOnlineState().then(()=>multiplayer?.loadChat()).catch(()=>{})}
async function pollOnlineState(){const token=store.state.account?.token;if(!api.configured||!token)return;const matchId=store.state.online?.matchId;if(matchId){const data=await api.state(token,matchId);applyOnlineMatch(data.match);return}const lobby=store.state.online?.lobby;if(lobby){const data=await api.getLobby(token,lobby.id);applyOnlineLobby(data.lobby);if(data.lobby.matchId){store.state.online.matchId=data.lobby.matchId;store.save();const state=await api.state(token,data.lobby.matchId);applyOnlineMatch(state.match)}}}

function saveBackend(){api.setUrl(resources.config.backendUrl);store.update(s=>s.backendUrl=resources.config.backendUrl,'backend-url');$('#backendUrlInput').value=resources.config.backendUrl;toast('The supplied version 1 backend URL has been restored.')}
async function testBackend(){try{$('#backendStatusText').textContent='Testing…';const [health,serverConfig,manifest]=await Promise.all([api.health(),api.config(),api.manifest()]);$('#backendStatusText').textContent=`Healthy · ${health.version||serverConfig.version||'v1'}`;const routes=manifest.routes||manifest.endpoints||[];toast(`Backend connected. ${Array.isArray(routes)?routes.length:'API'} routes available.`)}catch(error){$('#backendStatusText').textContent='Connection failed';toast(error.message,'error')}}
function resetLocal(){if(!confirm('Erase this browser’s Killer In The Keep save, settings, match, notes, and backend URL?'))return;clearInterval(botTimer);clearInterval(pollTimer);store.reset();store.state.backendUrl=resources.config.backendUrl;store.save();api.setUrl(resources.config.backendUrl);renderAll();toast('Local save reset.')}
function applySettings(){const s=store.state.settings;document.body.classList.toggle('reduced-motion',s.reducedMotion);document.body.classList.toggle('high-contrast',s.highContrast);document.body.classList.toggle('large-text',s.largeText);document.documentElement.style.setProperty('--scale',String((s.scale||100)/100))}

async function sendControlAction(action,fallback){fallback?.();if(store.state.session.mode!=='online'||!store.state.online?.matchId)return;try{const sequence=Number(store.state.online.clientSequence||0)+1;store.state.online.clientSequence=sequence;store.save();await api.input(store.state.account.token,store.state.online.matchId,action,{clientSequence:sequence,location:map.currentLocation(),position:{x:map.position.x,y:0,z:map.position.y},rotation:map.facing})}catch(error){toast(error.message,'error')}}
async function leaveLiveMatch(){try{const token=store.state.account?.token,matchId=store.state.online?.matchId;if(token&&matchId)await api.leaveMatch(token,matchId)}catch(error){console.warn(error)}store.update(s=>{s.online.matchId='';s.online.match=null;s.online.chat=[];s.session.mode='offline';s.session.started=false;s.session.phase='lobby';s.session.party=[];s.session.positions={};s.session.entities=[];s.session.playerId='local-player';s.session.role=null},'online-leave');navigate('home');toast('Left the connected match.')}
function setupInstall(){window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;$('#installAppButton').hidden=false;$('#settingsInstallButton').disabled=false});window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;$('#installAppButton').hidden=true;toast('Killer In The Keep installed.')});if(window.matchMedia('(display-mode: standalone)').matches){$('#settingsInstallButton').textContent='App is installed';$('#settingsInstallButton').disabled=true}}
async function installApp(){if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;$('#installAppButton').hidden=true;return}toast('Use your browser’s Install App or Add to Home Screen command if the install prompt is unavailable.')}
function registerServiceWorker(){if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').catch(error=>console.warn('Service worker registration failed',error))}

function partyHtml(party){return party.map(p=>{const c=resources.characters.find(ch=>ch.id===p.characterId);return `<div class="party-member"><img src="${escapeHtml(c?.portrait||'')}" alt=""><span><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(c?.name||'Adventurer')} · ${escapeHtml(c?.className||'')}</small></span><i class="status-dot"></i></div>`}).join('')||'<p class="muted">No active party.</p>'}
function fillSelect(select,items){const value=select.value;select.innerHTML=items.map(i=>`<option value="${i.id}">${escapeHtml(i.name)}</option>`).join('');if(items.some(i=>i.id===value))select.value=value}
function controlsTable(actions){return `<table class="controls-table"><thead><tr><th>Action</th><th>Keyboard</th><th>Arrow Keys</th><th>NumPad</th><th>Xbox</th><th>Nintendo</th><th>PlayStation</th></tr></thead><tbody>${actions.map(a=>`<tr><td>${escapeHtml(a.label)}</td><td>${escapeHtml(a.bindings?.pc||'—')}</td><td>${escapeHtml(a.bindings?.arrowKeys||'—')}</td><td>${escapeHtml(a.bindings?.numpad||'—')}</td><td>${escapeHtml(a.bindings?.xbox||'—')}</td><td>${escapeHtml(a.bindings?.switch||'—')}</td><td>${escapeHtml(a.bindings?.playstation||'—')}</td></tr>`).join('')}</tbody></table>`}
function title(s){return String(s||'').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/[-_]/g,' ').replace(/\b\w/g,c=>c.toUpperCase())}
